import {
  Collapsible as CollapsiblePrimitive,
  useCollapsible,
  useCollapsibleContext,
} from '@ark-ui/solid/collapsible';
import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { children, splitProps } from 'solid-js';
import { ChevronDownIcon } from '@/lib/moduix/icons/ui/Icons';
import styles from './Collapsible.module.css';

function Collapsible(props: ComponentProps<typeof CollapsiblePrimitive.Root>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CollapsiblePrimitive.Root
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="collapsible-root"
    />
  );
}

function CollapsibleRootProvider(props: ComponentProps<typeof CollapsiblePrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CollapsiblePrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="collapsible-root-provider"
    />
  );
}

function CollapsibleTrigger(props: ComponentProps<typeof CollapsiblePrimitive.Trigger>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <CollapsiblePrimitive.Trigger
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.trigger, local.class)}
      {...others}
      data-slot="collapsible-trigger"
    />
  );
}

function CollapsibleIndicator(props: ComponentProps<typeof CollapsiblePrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <CollapsiblePrimitive.Indicator
      class={clsx(styles.indicator, local.class)}
      {...others}
      data-slot="collapsible-indicator"
    >
      {resolvedChildren() ?? <ChevronDownIcon />}
    </CollapsiblePrimitive.Indicator>
  );
}

function CollapsibleContent(props: ComponentProps<typeof CollapsiblePrimitive.Content>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CollapsiblePrimitive.Content
      class={clsx(styles.content, local.class)}
      {...others}
      data-slot="collapsible-content"
    />
  );
}

function CollapsibleBody(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.div
      class={clsx(styles.body, local.class)}
      {...others}
      data-scope="collapsible"
      data-part="body"
      data-slot="collapsible-body"
    />
  );
}

const CollapsibleContext = CollapsiblePrimitive.Context;

export {
  Collapsible,
  CollapsibleBody,
  CollapsibleContent,
  CollapsibleContext,
  CollapsibleIndicator,
  CollapsibleRootProvider,
  CollapsibleTrigger,
  useCollapsible,
  useCollapsibleContext,
};

export type {
  CollapsibleContentProps,
  CollapsibleContextProps,
  CollapsibleIndicatorProps,
  CollapsibleOpenChangeDetails,
  CollapsibleRootProps,
  CollapsibleRootProviderProps,
  CollapsibleTriggerProps,
  UseCollapsibleContext,
  UseCollapsibleProps,
  UseCollapsibleReturn,
} from '@ark-ui/solid/collapsible';

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    width: 100%;
    min-width: 0;
    flex-direction: column;
    color: var(--moduix-color-foreground);
  }

  .trigger {
    box-sizing: border-box;
    display: flex;
    width: 100%;
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-collapsible-trigger-gap, var(--moduix-spacing-2));
    margin: 0;
    border: 0;
    padding-block: var(--moduix-collapsible-trigger-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-collapsible-trigger-padding-x, 0);
    background-color: transparent;
    color: inherit;
    font: inherit;
    font-size: var(--moduix-collapsible-trigger-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-line-height-text-sm);
    text-align: start;
    user-select: none;
    outline: 0;
    cursor: pointer;

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-inset-offset);
    }

    &:is([disabled], [data-disabled]) {
      opacity: var(--moduix-opacity-disabled);
      cursor: default;
    }
  }

  .indicator {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--moduix-collapsible-indicator-size, var(--moduix-spacing-3));
    height: var(--moduix-collapsible-indicator-size, var(--moduix-spacing-3));
    flex-shrink: 0;
    transition: transform var(--moduix-transition-default);

    & svg {
      width: 100%;
      height: 100%;
    }

    &[data-state='open'] {
      transform: rotate(180deg);
    }
  }

  .content {
    box-sizing: border-box;
    overflow: hidden;
    color: var(--moduix-collapsible-content-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-collapsible-content-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-line-height-text-sm);

    &[data-state='open'] {
      animation: global(moduix-collapsible-content-open) var(--moduix-transition-default);
    }

    &[data-state='closed'] {
      animation: global(moduix-collapsible-content-closed) var(--moduix-transition-default);
    }

    &[data-has-collapsed-size][data-state='open'] {
      animation-name: global(moduix-collapsible-content-open-partial);
    }

    &[data-has-collapsed-size][data-state='closed'] {
      animation-name: global(moduix-collapsible-content-closed-partial);
    }
  }

  .body {
    display: grid;
    gap: var(--moduix-collapsible-body-gap, var(--moduix-spacing-2));
    min-width: 0;
    padding: var(--moduix-collapsible-body-padding, 0);
  }

  @media (prefers-reduced-motion: reduce) {
    .indicator {
      transition: none;
    }

    .content[data-state] {
      animation-duration: 1ms;
      animation-delay: 0ms;
    }
  }
}
